/* Section Container Spacing & Typography */
.sl-method-video {
    font-family: inherit;
}
.sl-method-video .sl-container-boxed {
    max-width: 1240px;
    margin: 0 auto;
    padding-left: 1.5rem;
    padding-right: 1.5rem;
}
@media (min-width: 992px) {
    .sl-method-video .sl-container-boxed {
        padding-left: 2.5rem;
        padding-right: 2.5rem;
    }
}
.sl-method-video .sl-badge-eyebrow {
    background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent);
    color: var(--smartlearn-primary);
    font-size: 0.85rem;
    font-weight: 750;
    letter-spacing: 0.12em;
}
.sl-method-video .sl-method-heading {
    font-size: clamp(2.2rem, 3.6vw, 3.1rem);
    font-weight: 800;
    line-height: 1.16;
    letter-spacing: -0.035em;
    color: var(--smartlearn-text);
}
.sl-method-video .sl-method-lead {
    font-size: 1.125rem;
    line-height: 1.75;
    color: var(--smartlearn-text-muted);
    opacity: 0.95;
}

/* Pill Accordion List & Capsule Styling */
.sl-method-video .sl-accordion-btn {
    padding: 1.15rem 1.65rem;
    background-color: transparent;
    border: 1.5px solid color-mix(in srgb, var(--smartlearn-primary) 30%, var(--smartlearn-card-border)) !important;
    color: var(--smartlearn-text);
    transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    cursor: pointer;
    box-shadow: 0 4px 15px rgba(0,0,0,0.02);
}
.sl-method-video .sl-accordion-btn:hover {
    border-color: var(--smartlearn-primary) !important;
    background-color: color-mix(in srgb, var(--smartlearn-primary) 8%, transparent);
    transform: translateX(4px);
}
.sl-method-video .sl-accordion-title {
    font-size: 0.98rem;
    letter-spacing: 0.06em;
    font-weight: 750;
}
.sl-method-video .sl-accordion-icon {
    width: 42px;
    height: 42px;
    background-color: color-mix(in srgb, var(--smartlearn-text) 12%, transparent);
    color: var(--smartlearn-text);
    transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}
.sl-method-video .sl-accordion-icon i {
    font-size: 14px;
    transition: transform 0.3s ease;
}
.sl-method-video .sl-accordion-item.active .sl-accordion-btn {
    border-color: var(--smartlearn-primary) !important;
    background-color: color-mix(in srgb, var(--smartlearn-primary) 10%, transparent);
}
.sl-method-video .sl-accordion-item.active .sl-accordion-icon {
    background-color: var(--smartlearn-primary);
    color: #FFFFFF !important;
    transform: rotate(90deg);
}
.sl-method-video .sl-accordion-body-wrapper {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.3s ease;
    opacity: 0;
}
.sl-method-video .sl-accordion-item.active .sl-accordion-body-wrapper {
    max-height: 500px;
    opacity: 1;
}
.sl-method-video .sl-accordion-body {
    padding: 1.25rem 1.5rem 0.5rem 1.25rem;
    font-size: 1.05rem;
    line-height: 1.75;
}
.sl-method-video .sl-video-box {
    border-color: var(--smartlearn-card-border) !important;
}
.sl-method-video .sl-video-overlay {
    background: linear-gradient(180deg, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.5) 100%);
    transition: background 0.3s ease;
}
.sl-method-video .sl-play-btn {
    width: 68px;
    height: 68px;
    background-color: var(--smartlearn-primary);
    color: #FFFFFF !important;
    font-size: 1.5rem;
    transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.2s ease;
    cursor: pointer;
}
.sl-method-video .sl-video-box:hover .sl-play-btn {
    transform: scale(1.12);
    box-shadow: 0 15px 30px rgba(0,0,0,0.3);
}
.sl-method-video .sl-video-time-badge {
    background-color: rgba(0, 0, 0, 0.65);
    color: #FFFFFF;
    backdrop-filter: blur(8px);
}

js:
(function() {
    const root = document.querySelector('.sl-method-video');
    if (!root) return;

    // Accordion Logic
    const accordionItems = root.querySelectorAll('.sl-accordion-item');
    accordionItems.forEach(item => {
        const btn = item.querySelector('.sl-accordion-header');
        if (!btn) return;
        btn.addEventListener('click', (e) => {
            if (document.body.classList.contains('sl-editor-mode')) return;
            e.preventDefault();
            const isOpen = item.classList.contains('active');
            accordionItems.forEach(other => {
                if (other !== item) other.classList.remove('active');
            });
            if (isOpen) {
                item.classList.remove('active');
            } else {
                item.classList.add('active');
            }
        });
    });

    // Video Playback Logic
    const videoBox = root.querySelector('.sl-video-box');
    const playBtn = root.querySelector('.sl-play-btn');
    const poster = root.querySelector('.sl-video-poster');
    const overlay = root.querySelector('.sl-video-overlay');
    const timeBadge = root.querySelector('.sl-video-time-badge');
    const urlEl = root.querySelector('.sl-item-video-url');

    if (videoBox && playBtn) {
        playBtn.addEventListener('click', (e) => {
            if (document.body.classList.contains('sl-editor-mode')) return;
            e.preventDefault();
            e.stopPropagation();

            const videoUrl = urlEl ? urlEl.innerText.trim() : 'https://www.youtube.com/embed/dQw4w9WgXcQ';
            if (!videoUrl) return;

            if (poster) poster.style.display = 'none';
            if (overlay) overlay.style.display = 'none';
            if (timeBadge) timeBadge.style.display = 'none';
            playBtn.style.display = 'none';

            const iframe = document.createElement('iframe');
            iframe.src = videoUrl + (videoUrl.includes('?') ? '&' : '?') + 'autoplay=1';
            iframe.style.position = 'absolute';
            iframe.style.top = '0';
            iframe.style.left = '0';
            iframe.style.width = '100%';
            iframe.style.height = '100%';
            iframe.style.minHeight = '290px';
            iframe.style.border = 'none';
            iframe.style.zIndex = '10';
            iframe.setAttribute('allow', 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share');
            iframe.setAttribute('allowfullscreen', 'true');
            videoBox.appendChild(iframe);
        });
    }
})();
